use crate::{care_policy as c,sync_codec as codec};
use serde_json::{Value,json};
pub fn run(path:&str){let v:Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();let mut count=0;
 let astral=v["astralInput"].as_str().unwrap();let parsed=crate::log_parser::parse(astral);let rust_units:Vec<u16>=parsed.items[0].detail.encode_utf16().collect();let kotlin_units:Vec<u16>=v["astralDetailUTF16"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap() as u16).collect();assert_ne!(rust_units,kotlin_units);assert!(kotlin_units.contains(&0xd83d));assert!(!kotlin_units.contains(&0xde00));assert!(rust_units.contains(&0xde00));eprintln!("PASS pinned expected astral45UTF16 fallback divergence: Kotlin halfsurrogate vs Rust fullscalar; production native parser remains disabled, no universal parser parity");
 for row in v["cases"].as_array().unwrap(){let input=row["input"].as_str().unwrap();assert_eq!(c::is_logging_intent(input),row["intent"].as_bool().unwrap());let gate=c::CareLogConsentGate::new();let p=gate.propose("owner-A","2024-03-01",input);assert_eq!(p.is_some(),row["present"].as_bool().unwrap());if let Some(p)=p{let t=&p.interpretation;assert_eq!(json!(t.flow_level_result),row["flow"]);assert_eq!(json!(t.energy_result),row["energy"]);assert_eq!(json!(t.mood_result),row["mood"]);assert_eq!(json!(t.symptoms_result),row["symptoms"]);assert_eq!(json!(t.pain_intensity_result),row["pain"]);
 assert!(gate.confirm("wrong",&p.owner_id).is_none());assert!(gate.confirm(&p.id,"owner-B").is_none());assert!(gate.confirm(&p.id,&p.owner_id).is_some());assert!(gate.confirm(&p.id,&p.owner_id).is_none());
 let old=c::CycleDayLog{date_string:"2024-03-01".into(),flow_level:"MODERATE".into(),energy_level:"".into(),mood_level:"".into(),symptoms_csv:" cramps,headache,cramps ".into(),vaginal_health_csv:"".into(),urinary_health_csv:"".into(),cervical_mucus:"".into(),ovulation_test:"NONE".into(),bbt_celsius:36.6f32 as f64,sleep_hours:7.3f32 as f64,sleep_quality:"".into(),water_glasses:4,notes:"existing-private-notes".into(),pain_intensity:1};let m=c::merge(&old,t);
 let log=codec::CycleDayLog{date:m.date_string,flow:m.flow_level,energy:m.energy_level,mood:m.mood_level,symptoms:m.symptoms_csv,vaginal_health:m.vaginal_health_csv,urinary_health:m.urinary_health_csv,cervical_mucus:m.cervical_mucus,ovulation_test:m.ovulation_test,bbt_celsius:m.bbt_celsius as f32,sleep_hours:m.sleep_hours as f32,sleep_quality:m.sleep_quality,water_glasses:m.water_glasses as i32,notes:m.notes,pain_intensity:m.pain_intensity};assert_eq!(codec::log_payload(&log),row["mergedPayload"].as_str().unwrap());}
 count+=1;
 }
 let gate=c::CareLogConsentGate::new();let a=gate.propose("A","2024-03-01","I have cramps").unwrap();let b=gate.propose("A","2024-03-02","I feel tired").unwrap();assert_ne!(a.id,b.id);assert!(gate.confirm(&a.id,"A").is_none());assert_eq!(gate.confirm(&b.id,"A").unwrap().date,"2024-03-02");gate.propose("A","2024-03-01","I have cramps");gate.cancel();assert!(gate.confirm(&b.id,"A").is_none());let p=gate.propose("A","2024-03-01","I have cramps").unwrap();assert!(gate.propose("A","2024-03-01","hello").is_none());assert!(gate.confirm(&p.id,"A").is_none());
 for wrong in ["", "wrong", "\0", "é"]{let gate=c::CareLogConsentGate::new();let p=gate.propose("A","2024-03-01","I have cramps").unwrap();assert!(gate.confirm(wrong,"A").is_none());assert!(gate.confirm(&p.id,wrong).is_none());assert!(gate.confirm(&p.id,"A").is_some());}
 eprintln!("PASS{count} fresh current Kotlin care intent/proposal/parsed/merge cases plus relational ID/owner/edit/cancel/one-shot gate schedules; synthetic only");
}
